    bullets: [],
    kits: map.kits.map((k) => ({ x: k.x, y: k.y, active: false, respawnIn: KIT.firstSpawn })),
    zone: { x: W / 2, y: H / 2, radius: ZONE_START_RADIUS },
    over: false,
    winner: null,
    endReason: null,
  };
