    repairKits: round.kits.map((k) => ({ ...k })),
    zone: {
      x: round.zone.x,
      y: round.zone.y,
      radius: round.zone.radius,
      finalRadius: ZONE.finalRadius,
      shrinkStart: ZONE.startShrink,
      shrinkEnd: ZONE.endShrink,
      damagePerSecond: ZONE.damagePerSecond,
    },
