function stepBullets(round, events) {
  for (const b of round.bullets) {
    if (b.dead) continue;
    b.age += DT;
    if (b.age > BULLET_LIFETIME) {
      b.dead = true;
      events.push({ type: 'fizzle', x: b.x, y: b.y, owner: b.owner });
      continue;
    }
