          if (c) break;
        }
      }
      if (c) {
        if (b.bouncesLeft > 0) {
          b.bouncesLeft--;
          b.bounced = true;
          b.x += c.nx * c.depth;
          b.y += c.ny * c.depth;
          const dot = b.vx * c.nx + b.vy * c.ny;
          b.vx -= 2 * dot * c.nx;
          b.vy -= 2 * dot * c.ny;
          events.push({ type: 'ricochet', x: b.x, y: b.y, owner: b.owner, nx: c.nx, ny: c.ny });
        } else {
          b.dead = true;
          events.push({ type: 'impact', x: b.x, y: b.y, owner: b.owner });
        }
